function itemDetail(id){const i=D.items.find(x=>x.id===id);if(!i)return notice(Error('PM_NOT_FOUND'));const workflowActions=[];if(readable()){if((manage()||i.owner_id===L.user_id)&&i.kind==='phase'&&['planned','in_progress','on_hold'].includes(i.status))workflowActions.push(button(advanced()?'stage_gate':'finish_phase','finish_phase',`data-id="${i.id}"`,true));if((manage()||i.owner_id===L.user_id)&&((i.kind==='deliverable'&&['in_progress','changes_requested'].includes(i.status))||(i.kind==='change'&&['request','assessment'].includes(i.status))))workflowActions.push(button('submit','workflow',`data-value="submit" data-id="${i.id}"`,true));if((L.admin||i.approver_id===L.user_id)&&((i.kind==='phase'&&i.status==='review')||(i.kind==='deliverable'&&i.status==='submitted')||(i.kind==='change'&&i.status==='approval'))){for(const a of ['approve','request_changes',...(i.kind==='phase'?['hold']:i.kind==='change'?['reject']:[])])workflowActions.push(button(a,'workflow',`data-value="${a}" data-id="${i.id}"`,a==='approve'))}if(manage()&&i.kind==='change'&&i.status==='approved')workflowActions.push(button('apply_change','workflow',`data-value="apply_change" data-id="${i.id}"`,true));if(manage()&&i.kind==='change'&&i.status==='implementation')workflowActions.push(button('close_change','workflow',`data-value="close_change" data-id="${i.id}"`));}
 const details=[['owner',person(i.owner_id)],['approver',person(i.approver_id)],['start_date',date(i.start_date)],['due_date',date(i.due_date)],['progress',num(i.progress)+' %'],...['phase','work_package','deliverable'].map(k=>[k,D.items.find(x=>x.id===i[k+'_id'])?.title||'—'])];for(const [k,,label] of itemDataFields[i.kind]||[])if(i.data[k]!==undefined)details.push([label||k,typeof i.data[k]==='boolean'?t(i.data[k]?'yes':'no'):i.data[k]]);
 if(['phase','work_package'].includes(i.kind)){const costs=D.costs.filter(c=>c.item_id===id||(i.kind==='phase'&&D.items.find(x=>x.id===c.item_id)?.phase_id===id));for(const key of ['committed','actual'])details.push([key,money(costs.reduce((sum,c)=>sum+Number(c[key]||0),0))]);}
 const comments=D.comments.filter(c=>c.item_id===id);const body=`<div class="pmWide"><div class="pmTools">${badge(i.status)}${badge(i.priority)}${i.kind==='risk'?`${badge(['risk_low','risk_important','risk_critical'][Core.riskHealth(i)],'pmHealth'+Core.riskHealth(i))} ${Core.score(i)}/25`:''}</div><p style="white-space:pre-wrap">${esc(i.description)}</p><div class="pmKpis">${details.map(([k,v])=>`<div><div class="pmMeta">${esc(t(k))}</div><b>${esc(v)}</b></div>`).join('')}</div>${i.data.checklist?.length?`<h3>${esc(t('checklist'))}</h3>${i.data.checklist.map(c=>`<p>${c.done?'✓':'○'} ${esc(c.text)}</p>`).join('')}`:''}${i.data.dependencies?.length?`<h3>${esc(t('dependencies'))}</h3>${i.data.dependencies.map(id=>{const dep=D.items.find(x=>x.id===id);return dep?`<p>${linkItem(dep)} ${badge(dep.status)}</p>`:''}).join('')}`:''}${i.data.impacts?.length?`<h3>${esc(t('change_targets'))}</h3>${i.data.impacts.map(c=>`<p>${esc(D.items.find(x=>x.id===c.item_id)?.title||'—')} · ${c.start_date?date(c.start_date)+' → ':''}${c.due_date?date(c.due_date):''}${c.budget!==undefined?' · '+money(c.budget):''}</p>`).join('')}`:''}<div class="pmTools">${canEditItem(i)?button('edit','edit_item',`data-id="${i.id}"`):''}${manage()?`<button type="button" class="arcButton danger" data-pm-action="delete_item" data-id="${i.id}">${esc(t('delete_item'))}</button>`:''}${workflowActions.join('')}${edit()?button('comment','comment',`data-id="${i.id}"`):''}${edit()&&!['approved','completed','submitted'].includes(i.status)?button('upload','file',`data-id="${i.id}"`):''}${manage()&&['phase','work_package'].includes(i.kind)?button('create_purchase','purchase',`data-id="${i.id}"`)+button('link_purchase','link',`data-kind="purchase" data-id="${i.id}"`)+button('reserve','reserve',`data-id="${i.id}"`):''}${edit()&&L.admin&&i.kind==='lesson'?button('create_knowledge','knowledge',`data-id="${i.id}"`):''}</div><h3>${esc(t('attachments'))}</h3>${fileList(id)}<h3>${esc(t('comments'))}</h3>${comments.map(c=>`<div class="arcPanel pmPanel"><div class="pmMeta">${esc(person(c.created_by))} · ${date(c.created_at)}</div><p style="white-space:pre-wrap">${esc(c.body)}</p></div>`).join('')||`<p>${esc(t('empty'))}</p>`}<h3>${esc(t('history'))}</h3>${activityHTML(D.activity.filter(a=>a.row_id===id).slice(0,30))}</div>`;dialog(i.reference+' — '+i.title,body);}
function deleteItemForm(id){
 const i=D?.items.find(x=>x.id===id);if(!i||!manage())return;
 const blockers=D.items.filter(x=>x.id!==id&&([x.phase_id,x.work_package_id,x.deliverable_id,x.data?.task_id,x.data?.target_id].includes(id)||(x.data?.dependencies||[]).includes(id)||(x.data?.impacts||[]).some(v=>v.item_id===id)));
 const locked=D.items.some(x=>[i.phase_id,i.work_package_id,i.deliverable_id].includes(x.id)&&['completed','approved','review','submitted'].includes(x.status));
 const body=`<div class="pmWide"><p><strong>${esc(i.reference+' — '+i.title)}</strong></p><p>${esc(t('delete_item_help'))}</p>${locked?`<p class="pmError">${esc(t('PM_PARENT_LOCKED'))}</p>`:''}${blockers.length?`<p class="pmError">${esc(t('PM_DELETE_REFERENCED'))}</p>${itemRows(blockers)}`:''}</div>`+(!locked&&!blockers.length?field('confirmed','delete_item_confirm',false,'checkbox',[],'required'):'');
 const pid=D.project.id;
 const d=dialog(t('delete_item'),body,locked||blockers.length?null:async f=>{await rpc('delete_item',{project_id:pid,id:i.id,version:i.version,confirmed:!!fval(f,'confirmed')},true);closeDialog();await reload();notice('item_deleted',true)},'delete_permanently');
 if(d){d.querySelector('[type=submit]')?.classList.replace('primary','danger');d.querySelector('[data-pm-close]').textContent=t('cancel');}
}
