async function workflow(a,i){if(!i)return;if(['request_changes','hold','reject'].includes(a))return reasonDialog(a,i);if(!confirm(t(a)+' — '+i.reference+' ?'))return;await run(async()=>{await rpc(a,{project_id:D.project.id,id:i.id,version:i.version},true);closeDialog();await reload(i.id)})}
