async function phaseClosure(id){const i=D.items.find(x=>x.id===id);if(!i)return;try{const checks=await rpc('checks',{project_id:D.project.id,id});const blocked=checks.some(c=>c.blocking&&c.count>0);dialog(t(advanced()?'stage_gate':'finish_phase')+' · '+i.title,`<div class="pmWide">${checksHTML(checks)}</div>`,blocked?null:async()=>{await rpc('submit',{project_id:D.project.id,id,version:i.version},true);closeDialog();await reload(id)},i.approver_id?'submit':'finish_phase')}catch(e){notice(e)}}
