function fileForm(itemId='',previous=''){const old=D.files.find(f=>f.id===previous);dialog(t(old?'new_version':'upload'),field('filename','filename',old?.filename||'','text',[],'required')+field('item_id','impacted_elements',itemId,'select',D.items.filter(i=>!['completed','approved','submitted'].includes(i.status)).map(i=>({id:i.id,name:i.reference+' · '+i.title})))+`<label class="pmWide">${esc(t('file'))}<input type="file" name="upload" accept=".pdf,.png,.jpg,.jpeg,.txt,.csv,.docx,.xlsx,.pptx"></label><p class="pmMeta pmWide">${esc(t('file_help'))}</p>`+field('url','url','','url'),async f=>{const file=f.elements.upload.files[0],url=fval(f,'url');if((!!file)===(!!url))throw Error('PM_INVALID_FILE');let path=null;const projectId=D.project.id,c=await GamaCloud.db();if(file){if(file.size>20971520)throw Error('file_too_large');path=projectId+'/'+crypto.randomUUID()+'/'+file.name.replace(/[^\p{L}\p{N}._-]/gu,'_');const r=await c.storage.from('pm-documents').upload(path,file,{upsert:false});if(r.error)throw r.error}try{await rpc('file',{project_id:projectId,id:fval(f,'item_id')||null,filename:fval(f,'filename'),url:url||null,storage_path:path,supersedes_id:previous||null},true)}catch(e){if(path)await c.storage.from('pm-documents').remove([path]);throw e}closeDialog();await reload(itemId||null)})}
