function reportForm(type='project_report'){const sections=['overview','phases','tasks','milestones','control','budget','team','files','lesson'],defaults=type==='financial_report'?['overview','budget']:type==='lessons_report'?['overview','lesson']:type==='business_case'?['overview']:sections;dialog(t('generate_report'),field('report_type','reports',type||'project_report','select',choices(['progress_report','project_report','financial_report','closure_report','custom_report',...(advanced()?['business_case','highlight_report','stage_report','exception_report','lessons_report']:[])]),'required')+field('format','format','pdf','select',[{id:'pdf',name:'PDF'},{id:'xlsx',name:'Excel'}],'required')+field('sections','sections',defaults,'multi',choices(sections),'required'),async form=>{const fresh=await rpc('detail',{project_id:D.project.id});await exportReport(fresh,fval(form,'report_type'),fval(form,'format'),fval(form,'sections'))},'export')}
function reportNotes(i){const lines=(itemDataFields[i.kind]||[]).filter(([k])=>i.data[k]!==undefined).map(([k,,label])=>t(label||k)+': '+(typeof i.data[k]==='boolean'?t(i.data[k]?'yes':'no'):String(i.data[k])));if(i.kind==='risk')lines.push(t('score')+': '+Core.score(i)+'/25');if(i.data.checklist?.length)lines.push(t('checklist')+': '+i.data.checklist.map(c=>(c.done?'[x] ':'[ ] ')+c.text).join('; '));if(i.data.dependencies?.length)lines.push(t('dependencies')+': '+i.data.dependencies.map(id=>D.items.find(x=>x.id===id)?.reference||'—').join(', '));return lines.join(' · ')}
async function exportReport(d,type,format,sections){const p=d.project,m=d.metrics,groups=[];const add=(name,rows)=>groups.push({name:t(name),rows});if(sections.includes('overview'))add('overview',[[p.reference,p.name],[t('status'),t(p.status)],[t('manager'),person(p.manager_id)],[t('start_date'),date(p.start_date)],[t('due_date'),date(p.due_date)],[t('progress'),num(m.progress)+' %'],[t('health'),t(['normal_health','attention','critical_health'][m.health])],[t('description'),p.description],...(p.mode==='advanced'?[[t('business_case'),p.business_case],[t('scope'),p.scope]]:[]),...Object.entries(p.closure||{}).filter(([k])=>['went_well','went_wrong','do_differently'].includes(k)).map(([k,v])=>[t(k),v])]);if(sections.includes('budget'))add('budget',[[t('currency'),p.currency],...[['budget',p.budget],['committed',m.committed],['actual',m.actual],['remaining',m.remaining],['forecast',m.forecast],...(p.mode==='advanced'?[['etc',m.etc],['vac',m.vac]]:[])].map(([k,v])=>[t(k),Number(v)]),[],...d.costs.map(c=>[c.order_number,t(c.status),Number(c.committed),Number(c.actual),c.currency,Number(c.exchange_rate)])]);for(const s of ['phases','tasks','milestones','control','lesson'])if(sections.includes(s)){const kinds={phases:['phase'],tasks:['task'],milestones:['milestone'],control:['risk','issue','change','decision','assumption','dependency'],lesson:['lesson']}[s];add(s,[[t('reference'),t('title'),t('status'),t('owner'),t('due_date'),t('progress'),t('description'),t('notes')],...d.items.filter(i=>kinds.includes(i.kind)).map(i=>[i.reference,i.title,t(i.status),person(i.owner_id),i.due_date||'',Number(i.progress),i.description,reportNotes(i)])])}if(sections.includes('team'))add('team',d.members.map(i=>[person(i.profile_id),t(i.role),i.capacity_hours]));if(sections.includes('files'))add('files',d.files.map(f=>[f.filename,f.version,person(f.created_by),f.created_at]));const filename=p.reference+'-'+type;if(format==='pdf'){await window.GamaCompany?.load(true);const pdf=window.GamaPdfTemplate?.layout({title:t(type),reference:p.reference,date:date(Core.today()),detail:p.name});if(!pdf)throw Error('PDF');for(const g of groups){pdf.section(g.name);for(const row of g.rows)pdf.text(row.join(' · '))}const doc=pdf.finish('Coco ERP · '+new Date().toISOString());if(window.GamaPdf?.save)await GamaPdf.save(doc,filename+'.pdf');else doc.save(filename+'.pdf')}else{await window.GamaExcelExport.loadXLSX();const wb=XLSX.utils.book_new();for(const g of groups){const ws=XLSX.utils.aoa_to_sheet(g.rows);ws['!cols']=[{wch:24},{wch:45},{wch:20},{wch:25},{wch:18},{wch:16},{wch:50},{wch:80}];XLSX.utils.book_append_sheet(wb,ws,g.name.slice(0,31).replace(/[\\/?*\[\]:]/g,' '))}XLSX.writeFile(wb,filename+'.xlsx')}}
async function fromSource(kind,id){if(!allowed())return;try{const s=await rpc('source',{kind,source_id:id});await open();if(s.project_id)return openProject(s.project_id);projectForm(null,'',{...s,source:{source_kind:kind,source_id:id}})}catch(e){window.gamaToast?.(error(e))}}
function sourceButton(kind,id,host){if(!allowed()||!host)return;const b=document.createElement('button');b.className='secondary';b.type='button';b.dataset.pmSource=kind;b.textContent=t('create_project');b.onclick=()=>fromSource(kind,id);host.appendChild(b)}
async function countAlerts(){if(!allowed())return 0;const epoch=authEpoch;const rows=await rpc('alerts');return epoch===authEpoch&&allowed()&&Array.isArray(rows)?rows.length:0}
async function mountAlerts(host){if(!allowed()||!host)return;const epoch=authEpoch,request=crypto.randomUUID();host.dataset.pmAlertsRequest=request;try{const alerts=await rpc('alerts');if(!host.isConnected||!allowed()||epoch!==authEpoch||host.dataset.pmAlertsRequest!==request||!Array.isArray(alerts))return;host.querySelector('[data-pm-alerts]')?.remove();const block=document.createElement('div');block.className='pmPanel';block.dataset.pmAlerts='';block.dataset.giIgnore='';window.ArcUI.render(block,`<h3>${esc(t('projects'))} · ${esc(t('actions_required'))}</h3>`+alertsHTML(alerts));block.querySelectorAll('[data-pm-project]').forEach(b=>b.onclick=()=>open({projectId:b.dataset.pmProject,itemId:b.dataset.pmItem,tab:b.dataset.pmTargetTab||undefined}));host.appendChild(block);return alerts.length}catch(e){if(host.isConnected&&epoch===authEpoch){const block=document.createElement('p');block.className='pmError';block.textContent=t('projects')+': '+error(e);host.appendChild(block)}}}
async function customerProjects(id,host){if(!allowed()||!id||!host)return;const epoch=authEpoch;host.dataset.pmCustomer=id;try{const [r,a,c]=await Promise.all([rpc('portfolio',{limit:12,filters:{customer_id:id}}),rpc('portfolio',{limit:1,filters:{customer_id:id,status:'active'}}),rpc('portfolio',{limit:1,filters:{customer_id:id,status:'completed'}})]);if(!host.isConnected||epoch!==authEpoch||!allowed()||host.dataset.pmCustomer!==id)return;window.ArcUI.render(host,`<div class="arcPanel pmPanel"><h3>${esc(t('projects'))}</h3><div class="pmTools"><span>${esc(t('active_projects'))}: ${a.total}</span><span>${esc(t('completed_projects'))}: ${c.total}</span><button class="arcButton secondary" data-all>${esc(t('portfolio'))} (${r.total})</button></div>${r.rows.map(p=>`<p><button class="arcButton pmLink" data-id="${p.id}">${esc(p.reference+' · '+p.name)}</button> ${badge(p.status)}</p>`).join('')}</div>`);host.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>open({projectId:b.dataset.id}));host.querySelector('[data-all]').onclick=()=>open({customerId:id})}catch(e){if(epoch===authEpoch)host.textContent=error(e)}}
// Project estimate form is rendered inside the common project surface.
document.addEventListener('submit',e=>{if(e.target.id!=='pmEstimate')return;e.preventDefault();run(async()=>{await rpc('update_project',{project_id:D.project.id,version:D.project.version,estimate_remaining:fval(e.target,'estimate_remaining')},true);await reload()})});
window.addEventListener('gama:auth-change',()=>{generation++;authEpoch++;document.querySelectorAll('[data-pm-alerts],#pmCustomerProjects').forEach(e=>e.replaceChildren());L=null;D=null;P=null;myData=null;filters={};taskFilters={};closeDialog();$('projects')?.replaceChildren()});
window.addEventListener('gama:modules-change',()=>{if(!allowed()){generation++;authEpoch++;document.querySelectorAll('[data-pm-alerts],#pmCustomerProjects').forEach(e=>e.replaceChildren());L=null;D=null;P=null;myData=null;closeDialog();$('projects')?.replaceChildren()}});
window.addEventListener('gama:language-change',()=>{if(!allowed()||!$('projects')?.classList.contains('active')||modal)return;shell();if(D)renderProject();else if(screen==='portfolio'&&P)portfolio();else if(screen==='my_work'&&myData)myWork();else if(L)templates()});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
